import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from '@/app/lib/analytics'

export default async function Home() {
  // Request data must be read during render; `headers()` can't be called
  // inside an `after` callback in a Server Component. Reading it here also
  // makes the page dynamic, so a page view is logged on every request
  // rather than once at build time.
  const requestHeaders = await headers()
  const userAgent = requestHeaders.get('user-agent') ?? 'unknown'
  const referrer = requestHeaders.get('referer')

  // Runs after the response has been sent, so analytics never delays the page.
  after(async () => {
    await logPageView({
      path: '/',
      userAgent,
      referrer,
      timestamp: new Date().toISOString(),
    })
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting! We&apos;re glad you&apos;re here.</p>
    </main>
  )
}

